// Receives sheet values pushed by a Google Apps Script running under the user's own account.
// Auth: a random push token generated by the script. Only its SHA-256 hash is stored.
// The first 'register' call claims the token slot; after that it can only be reset in the database.
import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "jsr:@supabase/supabase-js@2";

function json(body: unknown, status = 200) {
  return new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } });
}

async function sha256(s: string) {
  const d = new Uint8Array(await crypto.subtle.digest("SHA-256", new TextEncoder().encode(s)));
  return Array.from(d, (b) => b.toString(16).padStart(2, "0")).join("");
}

Deno.serve(async (req) => {
  if (req.method !== "POST") return json({ error: "Method not allowed" }, 405);
  const admin = createClient(Deno.env.get("SUPABASE_URL")!, Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!);

  let body: any;
  try { body = await req.json(); } catch { return json({ error: "Bad JSON" }, 400); }
  const token = String(body?.token ?? "");
  if (token.length < 32) return json({ error: "Missing token" }, 401);
  const hash = await sha256(token);

  const { data: row } = await admin.from("push_token").select("token_hash").eq("id", 1).maybeSingle();

  if (body.action === "register") {
    if (row && row.token_hash !== hash) return json({ error: "A push token is already registered" }, 409);
    if (!row) {
      const { error } = await admin.from("push_token").insert({ id: 1, token_hash: hash });
      if (error) return json({ error: error.message }, 500);
    }
    return json({ ok: true });
  }

  if (!row || row.token_hash !== hash) return json({ error: "Not authorised" }, 401);

  if (body.action === "config") {
    const { data, error } = await admin.from("projects")
      .select("id, name, spreadsheet_id, tab, range").eq("enabled", true).order("sort");
    if (error) return json({ error: error.message }, 500);
    return json({ projects: data });
  }

  if (body.action === "push") {
    const { data: projects } = await admin.from("projects").select("id, name");
    const known = new Map((projects ?? []).map((p) => [p.id, p.name]));
    const results = [];
    for (const r of (body.results ?? []) as { project_id: string; values?: string[][]; error?: string }[]) {
      if (!known.has(r.project_id)) continue;
      const name = known.get(r.project_id);
      const now = new Date().toISOString();
      if (r.error || !Array.isArray(r.values)) {
        await admin.from("snapshots").insert({ project_id: r.project_id, status: "failed", error: String(r.error ?? "No values").slice(0, 1000) });
        results.push({ project: name, status: "failed" });
        continue;
      }
      const { data: last } = await admin.from("snapshots").select("id, values")
        .eq("project_id", r.project_id).eq("status", "ok").order("synced_at", { ascending: false }).limit(1).maybeSingle();
      if (last && JSON.stringify(last.values) === JSON.stringify(r.values)) {
        await admin.from("snapshots").update({ checked_at: now }).eq("id", last.id);
        results.push({ project: name, status: "ok", changed: false });
      } else {
        const { error } = await admin.from("snapshots").insert({ project_id: r.project_id, status: "ok", values: r.values, synced_at: now, checked_at: now });
        results.push(error ? { project: name, status: "failed", error: error.message } : { project: name, status: "ok", changed: true });
      }
    }
    return json({ synced_at: new Date().toISOString(), results });
  }

  return json({ error: "Unknown action" }, 400);
});
